   224→// calculateChurnLimit based on the formula in the spec.
   225→//
   226→//	def get_validator_churn_limit(state: BeaconState) -> uint64:
   227→//	 """
   228→//	 Return the validator churn limit for the current epoch.
   229→//	 """
   230→//	 active_validator_indices = get_active_validator_indices(state, get_current_epoch(state))
   231→//	 return max(MIN_PER_EPOCH_CHURN_LIMIT, uint64(len(active_validator_indices)) // CHURN_LIMIT_QUOTIENT)
   232→func calculateChurnLimit(activeValidatorCount uint64) uint64 {
   233→	churnLimit := activeValidatorCount / params.BeaconConfig().ChurnLimitQuotient
   234→	if churnLimit < params.BeaconConfig().MinPerEpochChurnLimit {
   235→		return params.BeaconConfig().MinPerEpochChurnLimit
   236→	}
   237→	return churnLimit
   238→}
