   492→func isEligibleForActivationQueueElectra(activationEligibilityEpoch primitives.Epoch, effectiveBalance uint64) bool {
   493→	return activationEligibilityEpoch == params.BeaconConfig().FarFutureEpoch &&
   494→		effectiveBalance >= params.BeaconConfig().MinActivationBalance
   495→}
   496→
   497→// IsEligibleForActivation checks if the validator is eligible for activation.
   498→//
   499→// Spec pseudocode definition:
   500→//
   501→//	def is_eligible_for_activation(state: BeaconState, validator: Validator) -> bool:
   502→//	  """
   503→//	  Check if ``validator`` is eligible for activation.
   504→//	  """
   505→//	  return (
   506→//	      # Placement in queue is finalized
   507→//	      validator.activation_eligibility_epoch <= state.finalized_checkpoint.epoch
   508→//	      # Has not yet been activated
   509→//	      and validator.activation_epoch == FAR_FUTURE_EPOCH
   510→//	  )
   511→func IsEligibleForActivation(state state.ReadOnlyCheckpoint, validator *ethpb.Validator) bool {
   512→	finalizedEpoch := state.FinalizedCheckpointEpoch()
   513→	return isEligibleForActivation(validator.ActivationEligibilityEpoch, validator.ActivationEpoch, finalizedEpoch)
   514→}
   515→
   516→// IsEligibleForActivationUsingROVal checks if the validator is eligible for activation using the provided read only validator.
   517→func IsEligibleForActivationUsingROVal(state state.ReadOnlyCheckpoint, validator state.ReadOnlyValidator) bool {
   518→	return isEligibleForActivation(validator.ActivationEligibilityEpoch(), validator.ActivationEpoch(), state.FinalizedCheckpointEpoch())
   519→}
   520→
   521→// isEligibleForActivation carries out the logic for IsEligibleForActivation*
   522→func isEligibleForActivation(activationEligibilityEpoch, activationEpoch, finalizedEpoch primitives.Epoch) bool {
   523→	return activationEligibilityEpoch <= finalizedEpoch &&
   524→		activationEpoch == params.BeaconConfig().FarFutureEpoch
   525→}
   526→
   527→// LastActivatedValidatorIndex provides the last activated validator given a state
   528→func LastActivatedValidatorIndex(ctx context.Context, st state.ReadOnlyBeaconState) (primitives.ValidatorIndex, error) {
   529→	_, span := trace.StartSpan(ctx, "helpers.LastActivatedValidatorIndex")
   530→	defer span.End()
   531→	var lastActivatedvalidatorIndex primitives.ValidatorIndex
   532→	// linear search because status are not sorted
   533→	for j := st.NumValidators() - 1; j >= 0; j-- {
   534→		val, err := st.ValidatorAtIndexReadOnly(primitives.ValidatorIndex(j))
   535→		if err != nil {
   536→			return 0, err
   537→		}
   538→		if IsActiveValidatorUsingTrie(val, time.CurrentEpoch(st)) {
   539→			lastActivatedvalidatorIndex = primitives.ValidatorIndex(j)
   540→			break
   541→		}
   542→	}
   543→	return lastActivatedvalidatorIndex, nil
   544→}
   545→
   546→// IsSameWithdrawalCredentials returns true if both validators have the same withdrawal credentials.
   547→//
   548→//	return a.withdrawal_credentials[12:] == b.withdrawal_credentials[12:]
   549→func IsSameWithdrawalCredentials(a, b *ethpb.Validator) bool {
   550→	if a == nil || b == nil {
   551→		return false
   552→	}
   553→	if len(a.WithdrawalCredentials) <= 12 || len(b.WithdrawalCredentials) <= 12 {
   554→		return false
   555→	}
   556→	return bytes.Equal(a.WithdrawalCredentials[12:], b.WithdrawalCredentials[12:])
   557→}
   558→
   559→// IsFullyWithdrawableValidator returns whether the validator is able to perform a full
   560→// withdrawal. This function assumes that the caller holds a lock on the state.
   561→//
   562→// Spec definition:
   563→//
   564→//	def is_fully_withdrawable_validator(validator: Validator, balance: Gwei, epoch: Epoch) -> bool:
   565→//	    """
   566→//	    Check if ``validator`` is fully withdrawable.
   567→//	    """
   568→//	    return (
   569→//	        has_execution_withdrawal_credential(validator)  # [Modified in Electra:EIP7251]
   570→//	        and validator.withdrawable_epoch <= epoch
   571→//	        and balance > 0
   572→//	    )
   573→func IsFullyWithdrawableValidator(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch, fork int) bool {
   574→	if val == nil || balance <= 0 {
   575→		return false
   576→	}
   577→
   578→	// Electra / EIP-7251 logic
   579→	if fork >= version.Electra {
   580→		return val.HasExecutionWithdrawalCredentials() && val.WithdrawableEpoch() <= epoch
   581→	}
   582→
   583→	return val.HasETH1WithdrawalCredentials() && val.WithdrawableEpoch() <= epoch
   584→}
   585→
   586→// IsPartiallyWithdrawableValidator returns whether the validator is able to perform a
   587→// partial withdrawal. This function assumes that the caller has a lock on the state.
   588→// This method conditionally calls the fork appropriate implementation based on the epoch argument.
   589→func IsPartiallyWithdrawableValidator(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch, fork int) bool {
   590→	if val == nil {
   591→		return false
   592→	}
   593→
   594→	if fork < version.Electra {
   595→		return isPartiallyWithdrawableValidatorCapella(val, balance, epoch)
   596→	}
   597→
   598→	return isPartiallyWithdrawableValidatorElectra(val, balance, epoch)
   599→}
   600→
   601→// isPartiallyWithdrawableValidatorElectra implements is_partially_withdrawable_validator in the
   602→// electra fork.
   603→//
   604→// Spec definition:
   605→//
   606→// def is_partially_withdrawable_validator(validator: Validator, balance: Gwei) -> bool:
   607→//
   608→//	"""
   609→//	Check if ``validator`` is partially withdrawable.
   610→//	"""
   611→//	max_effective_balance = get_max_effective_balance(validator)
   612→//	has_max_effective_balance = validator.effective_balance == max_effective_balance  # [Modified in Electra:EIP7251]
   613→//	has_excess_balance = balance > max_effective_balance  # [Modified in Electra:EIP7251]
   614→//	return (
   615→//	    has_execution_withdrawal_credential(validator)  # [Modified in Electra:EIP7251]
   616→//	    and has_max_effective_balance
   617→//	    and has_excess_balance
   618→//	)
   619→func isPartiallyWithdrawableValidatorElectra(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch) bool {
   620→	maxEB := ValidatorMaxEffectiveBalance(val)
   621→	hasMaxBalance := val.EffectiveBalance() == maxEB
   622→	hasExcessBalance := balance > maxEB
   623→
   624→	return val.HasExecutionWithdrawalCredentials() &&
   625→		hasMaxBalance &&
   626→		hasExcessBalance
   627→}
   628→
   629→// isPartiallyWithdrawableValidatorCapella implements is_partially_withdrawable_validator in the
   630→// capella fork.
   631→//
   632→// Spec definition:
   633→//
   634→//	def is_partially_withdrawable_validator(validator: Validator, balance: Gwei) -> bool:
   635→//	    """
   636→//	    Check if ``validator`` is partially withdrawable.
   637→//	    """
   638→//	    has_max_effective_balance = validator.effective_balance == MAX_EFFECTIVE_BALANCE
   639→//	    has_excess_balance = balance > MAX_EFFECTIVE_BALANCE
   640→//	    return has_eth1_withdrawal_credential(validator) and has_max_effective_balance and has_excess_balance
   641→func isPartiallyWithdrawableValidatorCapella(val state.ReadOnlyValidator, balance uint64, epoch primitives.Epoch) bool {
   642→	hasMaxBalance := val.EffectiveBalance() == params.BeaconConfig().MaxEffectiveBalance
   643→	hasExcessBalance := balance > params.BeaconConfig().MaxEffectiveBalance
   644→	return val.HasETH1WithdrawalCredentials() && hasExcessBalance && hasMaxBalance
   645→}
   646→
   647→// ValidatorMaxEffectiveBalance returns the maximum effective balance for a validator.
   648→//
   649→// Spec definition:
   650→//
   651→//	def get_max_effective_balance(validator: Validator) -> Gwei:
   652→//	    """
   653→//	    Get max effective balance for ``validator``.
   654→//	    """
   655→//	    if has_compounding_withdrawal_credential(validator):
   656→//	        return MAX_EFFECTIVE_BALANCE_ELECTRA
   657→//	    else:
   658→//	        return MIN_ACTIVATION_BALANCE
   659→func ValidatorMaxEffectiveBalance(val state.ReadOnlyValidator) uint64 {
   660→	if val.HasCompoundingWithdrawalCredentials() {
   661→		return params.BeaconConfig().MaxEffectiveBalanceElectra
   662→	}
   663→	return params.BeaconConfig().MinActivationBalance
   664→}
